-- Merges four duplicate pairs I created: my name matching required an exact
-- match, so 'Pstereo' slid past the stored 'Pstereo Festival', and likewise
-- for Neopop, Ypsigrock and Sonorama. Each pair shares dates and sits within
-- ~1 km, so they were showing as two cards for one festival.
--
-- The OLDER row is kept in every case: it carries the image, and its
-- /festival/<slug> URL has had time to be indexed. Its name, venue, tags,
-- website and ticket link are raised to the better value, and the better of
-- the two lineups is kept. My duplicate row is then removed.

-- Pstereo: beholder «pstereo-festival», fjerner «pstereo»
-- Program: programmene er identiske; beholder det som ligger der.
update festivals set
  name = 'Pstereo',
  venue_name = 'Marinen',
  website_url = 'https://www.pstereo.no/',
  tags = array['Rock','Alternativ & Indie','Pop & Mainstream','Elektronisk & Dans','Hip-Hop & R&B','Soul & Funk','Folk & Americana']::text[]
where slug = 'pstereo-festival';

